update cms_article
category_id = #{categoryId}, tenant_id = #{tenantId}, title = #{title}, link = #{link}, image = #{image}, keywords = #{keywords}, description = #{description}, list_order_num = #{listOrderNum}, video_url = #{videoUrl}, list_show = #{listShow}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}, del_flag = #{delFlag},
where id = #{id}

mapper.select:
SELECT ca.id AS articleId, ca.image AS imageUrl, ca.title, ca.link, ca.create_time AS createTime, ca.description, rp.exam_record_id as examRecordId, rp.scores as score, rp.is_fill_again isFillAgain, S.research_id as researchId, S.project_name as projectName
FROM (SELECT a.article_id,a.research_id,d.project_name from research_info_article a, research_patient b, mp_person c, research_info d, mp_patient_account mpa where a.research_id = b.research_id and b.person_id = c.person_id AND mpa.person_id = c.person_id AND mpa.account_id = #{accountIds} AND a.research_id = d.id AND d.id in (${survivalResearchIds}))S
LEFT JOIN cms_article ca ON ca.id = s.article_id LEFT JOIN research_info_article_patient rp ON S.article_id = rp.article_id AND S.research_id = rp.research_id WHERE ca.del_flag = 'N' AND ca.type = 2 AND FIND_IN_SET( "2", ca.position_type ) AND rp.account_id = #{accountIds} AND rp.fill_status = #{fillStatus} order by rp.exam_record_id desc limit ${pageNo},${pageSize}
